import { describe, expect, test } from "bun:test";

import { bucketOf, type Bucket } from "./budget-table.ts";

describe("bucketOf", () => {
	// Each lower bound is inclusive and the size just below it falls in the
	// previous bucket.
	const boundaries: [number, Bucket][] = [
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
	];

	test.each(boundaries)("%d tokens is %s", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test("a fractional size just below a bound stays in the lower bucket", () => {
		expect(bucketOf(349.5)).toBe("tiny");
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"rejects %p with a RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

