import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";
import { bucketOf, histogram, turnSizes, type Bucket } from "./budget-table.ts";

describe("bucketOf", () => {
	// Each lower bound is inclusive and the size just below it falls in the
	// previous bucket.
	const boundaries: [number, Bucket][] = [
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
	];

	test.each(boundaries)("%d tokens is %s", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test("a fractional size just below a bound stays in the lower bucket", () => {
		expect(bucketOf(349.5)).toBe("tiny");
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"rejects %p with a RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("turnSizes", () => {
	const lead: HarnessMessage = { role: "assistant", content: "Before any prompt. ".repeat(40) };
	const firstPrompt: HarnessMessage = { role: "user", content: "Summarise the README." };
	const firstReply: HarnessMessage = { role: "assistant", content: "It explains setup. ".repeat(20) };
	const secondPrompt: HarnessMessage = { role: "user", content: "Thanks." };
	const secondReply: HarnessMessage = { role: "assistant", content: "Welcome." };
	const conversation = [lead, firstPrompt, firstReply, secondPrompt, secondReply];

	test("sizes each prompted Turn over its own messages, in order", () => {
		expect(turnSizes(conversation)).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("messages before the first prompt count toward no Turn", () => {
		expect(turnSizes(conversation)).toEqual(turnSizes(conversation.slice(1)));
	});

	test("a prompt with empty text still starts a sized Turn", () => {
		const emptyPrompt: HarnessMessage = { role: "user", content: "" };

		expect(turnSizes([lead, emptyPrompt, secondReply])).toEqual([
			approximateTokens([emptyPrompt, secondReply]),
		]);
	});

	test("only messages before any prompt give no sizes", () => {
		expect(turnSizes([lead])).toEqual([]);
	});
});

describe("histogram", () => {
	test("counts the sample sizes per bucket, largest bucket first", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("keeps empty buckets below huge at zero and leaves out an empty huge", () => {
		expect(histogram([23999, 100, 7000])).toEqual([
			{ bucket: "large", count: 2 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 1 },
		]);
	});

	test("an empty list gives a zero for every bucket but huge", () => {
		expect(histogram([])).toEqual([
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 0 },
		]);
	});
});

