const FROM: Record<Bucket, number> = {
	tiny: 0,
	small: 350,
	medium: 1800,
	large: 7000,
	huge: 24000,
};

/**
 * Bucket a Turn's estimated tokens fall in; lower bounds inclusive.
 * @throws {RangeError} for a negative or non-finite size.
