// suite: TT-5082
import { describe, expect, test } from "bun:test";

import { weighted } from "./budget-table.ts";

describe("weighted", () => {
	// The weight follows the size's bucket, so a bound changes the weight:
	// 349 is tiny at 0.5, 350 small at 1, and so on up.
	const cases: [number, number][] = [
		[0, 0],
		[349, 174.5],
		[350, 350],
		[1799, 1799],
		[1800, 2250],
		[6999, 8748.75],
		[7000, 10500],
		[23999, 35998.5],
		[24000, 54000],
	];

	test.each(cases)("%d tokens weighs %d", (size, weight) => {
		expect(weighted([size])).toEqual([weight]);
	});

	test("keeps the order of the sizes", () => {
		expect(weighted([8000, 120, 2400])).toEqual([12000, 60, 3000]);
	});

	test("leaves the result unrounded", () => {
		expect(weighted([101])).toEqual([50.5]);
	});

	test("no sizes give no weights", () => {
		expect(weighted([])).toEqual([]);
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => weighted([100, -1])).toThrow(RangeError);
	});
});

