	// 349 is tiny at 0.5 (174.5, rounded to 170), 350 small at 1, and so on up.
	const cases: [number, number][] = [
		[0, 0],
		[349, 170],
		[350, 350],
		[1799, 1800],
		[1800, 2250],
		[6999, 8750],
		[7000, 10500],
		[23999, 36000],
		[24000, 54000],
	];

	test.each(cases)("%d tokens weighs %d", (size, weight) => {
		expect(weighted([size])).toEqual([weight]);
	});

	test("keeps the order of the sizes", () => {
		expect(weighted([8000, 120, 2400])).toEqual([12000, 60, 3000]);
	});

	test.each([
		[364, 360],
		[365, 370],
		[1802, 2250],
	])("rounds the weighted size of %d to the nearest ten, halves up: %d", (size, weight) => {
		expect(weighted([size])).toEqual([weight]);
	});

	test("no sizes give no weights", () => {
		expect(weighted([])).toEqual([]);
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => weighted([100, -1])).toThrow(RangeError);
	});
});

