import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";
import { reconstructTurns } from "./turns.ts";

/** Turn-size buckets, smallest to largest. */
export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;

/** Size class of a Turn, by its estimated tokens. */
export type Bucket = (typeof BUCKETS)[number];

/** Inclusive lower bound of each bucket; each runs up to the next one's. */
const FROM: Record<Bucket, number> = {
	tiny: 0,
	small: 350,
	medium: 1800,
	large: 7000,
	huge: 24000,
};

/** What a Turn's size counts for, by its bucket. */
const WEIGHT: Record<Bucket, number> = {
	tiny: 0.5,
	small: 1,
	medium: 1.25,
	large: 1.5,
	huge: 2.25,
};

/** Row label a rendered table shows for each bucket. */
const LABEL: Record<Bucket, string> = {
	tiny: "crumbs",
	small: "bites",
	medium: "meals",
	large: "feasts",
	huge: "banquets",
};

/**
 * Bucket a Turn's estimated tokens fall in; lower bounds inclusive.
 * @throws {RangeError} for a negative or non-finite size.
 */
export function bucketOf(tokens: number): Bucket {
	if (!Number.isFinite(tokens) || tokens < 0) {
		throw new RangeError(`Turn size must be a finite, non-negative token count, got ${tokens}`);
	}
	let bucket: Bucket = BUCKETS[0];
	for (const candidate of BUCKETS) {
		if (tokens >= FROM[candidate]) bucket = candidate;
	}
	return bucket;
}

/**
 * Estimated tokens of each Turn in `messages`, in order, by `approximateTokens`
 * over the Turn's messages.
 *
 * `reconstructTurns` gathers any messages before the first user prompt (a
 * system prompt, say) into a leading Turn with no prompt. That Turn answers
 * no user and is dropped, so its messages count toward no size. A later Turn
 * is kept even when its prompt's text is empty: a Turn is recognised by
 * opening on a user message, not by having prompt text.
 */
export function turnSizes(messages: HarnessMessage[]): number[] {
	return reconstructTurns(messages)
		.filter((turn) => turn.messages[0]?.role === "user")
		.map((turn) => approximateTokens(turn.messages));
}

/**
 * How many sizes fall in each bucket, largest bucket first. Every bucket has
 * an entry, count 0 when empty, except `huge`, which is left out when empty.
 * @throws {RangeError} for a negative or non-finite size, as `bucketOf`.
 */
export function histogram(sizes: number[]): { bucket: Bucket; count: number }[] {
	const counts: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
	for (const size of sizes) counts[bucketOf(size)] += 1;
	return [...BUCKETS]
		.reverse()
		.filter((bucket) => bucket !== "huge" || counts.huge > 0)
		.map((bucket) => ({ bucket, count: counts[bucket] }));
}

/** Sum of the sizes, unweighted; 0 for no sizes. */
export function totalOf(sizes: number[]): number {
	let total = 0;
	for (const size of sizes) total += size;
	return total;
}

/**
 * Each size times its bucket's weight, rounded to the nearest 10 with halves
 * up (365 → 370), parallel to `sizes`.
 * @throws {RangeError} for a negative or non-finite size, as `bucketOf`.
 */
export function weighted(sizes: number[]): number[] {
	return sizes.map((size) => Math.round((size * WEIGHT[bucketOf(size)]) / 10) * 10);
}

/**
 * A number as a rendered table shows it: as is below 1000, otherwise in
 * thousands with one decimal and a `k`, halves up (1250 → `1.3k`).
 */
export function formatCount(n: number): string {
	if (n < 1000) return String(n);
	// Whole hundreds, not `toFixed(1)` on thousands: a half such as 1450 is
	// exact as 14.5, but 1.45 is not, and `toFixed` would round it down.
	const hundreds = Math.round(n / 100);
	return `${Math.floor(hundreds / 10)}.${hundreds % 10}k`;
}

/** Row label a rendered table shows for `bucket`. */
export function labelOf(bucket: Bucket): string {
	return LABEL[bucket];
}

