	])("rounds %d to the nearest hundred, halves up", (n, shown) => {
		expect(formatCount(n)).toBe(shown);
	});
});

describe("labelOf", () => {
	test.each([
		["tiny", "crumbs"],
		["small", "bites"],
		["medium", "meals"],
		["large", "feasts"],
		["huge", "banquets"],
	] as [Bucket, string][])("labels %s as %s", (bucket, label) => {
		expect(labelOf(bucket)).toBe(label);
	});
});

