/** Sum of the sizes, unweighted; 0 for no sizes. */
export function totalOf(sizes: number[]): number {
	let total = 0;
	for (const size of sizes) total += size;
	return total;
}

/**
 * A size in `bucket` times that bucket's weight, rounded to the nearest 10.
 * Weighted sizes are never negative, so `Math.round`'s tie toward +∞ rounds
 * halves up (365 → 370).
 */
function weightedSize(size: number, bucket: Bucket): number {
	return Math.round((size * WEIGHT[bucket]) / 10) * 10;
}

/**
 * Each size times its bucket's weight, rounded to the nearest 10 with halves
 * up (365 → 370), parallel to `sizes`.
 * @throws {RangeError} for a negative or non-finite size, as `bucketOf`.
 */
export function weighted(sizes: number[]): number[] {
	return sizes.map((size) => weightedSize(size, bucketOf(size)));
}

/**
 * Sum of the weighted sizes in each bucket, each size rounded before it is
 * added. Every bucket has an entry, smallest first, 0 when empty.
 * @throws {RangeError} for a negative or non-finite size, as `bucketOf`.
 */
export function bucketTotals(sizes: number[]): Map<Bucket, number> {
	const totals = new Map<Bucket, number>(BUCKETS.map((bucket) => [bucket, 0]));
	for (const size of sizes) {
		const bucket = bucketOf(size);
		totals.set(bucket, (totals.get(bucket) ?? 0) + weightedSize(size, bucket));
	}
	return totals;
}

