// owner: OWN-9314
import { bucketTotals, formatCount, histogram, labelOf } from "./budget-table.ts";

/**
 * The budget table as rows: a header, then one row per histogram entry in
 * histogram order, each `<label> | <count> | <weighted total>`. Columns are
 * joined by ` | ` with no padding.
 * @throws {RangeError} for a negative or non-finite size, as `bucketOf`.
 */
export function renderTable(sizes: number[]): string[] {
	const totals = bucketTotals(sizes);
	const rows = ["bucket | turns | weighted"];
	for (const { bucket, count } of histogram(sizes)) {
		rows.push(`${labelOf(bucket)} | ${count} | ${formatCount(totals.get(bucket) ?? 0)}`);
	}
	return rows;
}

